package com.nightcity.capriai;

import android.app.Activity;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.provider.Settings;
import android.widget.*;

public final class CapriPluginsActivity extends Activity {
    private android.content.SharedPreferences prefs;private LinearLayout page;
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("capri_settings",0);getWindow().setStatusBarColor(0xff080910);getWindow().setNavigationBarColor(0xff080910);ScrollView scroll=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(17),dp(18),dp(17),dp(28));page.setBackgroundColor(0xff080910);scroll.addView(page);TextView title=label("CAPRI // PLUGINS",22,Color.WHITE);title.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);page.addView(title);page.addView(label("MÓDULOS NATIVOS E CONEXÕES",10,0xff22f27a));card("WEB / NAVEGADOR","Pesquisa na web e abre links no navegador instalado.","web_plugin",true);card("AÇÕES DO ANDROID","Abre aplicativos, configurações e ações que o sistema permitir.","android_plugin",true);card("CONTEXTO DA TELA","Lê texto visível por acessibilidade. Você precisa ativar o serviço no Android.","screen_access_enabled",false);card("ENVIAR CONTEXTO À IA","Só envia o texto visível ao provedor de IA quando esta opção estiver ligada.","screen_context_to_ai",false);section("PERMISSÕES E CONEXÕES");Button access=button("ATIVAR / GERENCIAR LEITURA DA TELA");access.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));TextView status=label(CapriAccessibilityService.isEnabled(this)?"ACESSIBILIDADE: ATIVADA NO ANDROID":"ACESSIBILIDADE: AINDA NÃO AUTORIZADA",11,CapriAccessibilityService.isEnabled(this)?0xff22f27a:0xffffb14a);Button api=button("CONECTAR OPENAI / GEMINI");api.setOnClickListener(v->startActivity(new Intent(this,CapriSettingsActivity.class)));TextView note=label("OpenAI usa uma chave oficial de API. A conta do aplicativo ChatGPT não possui login OAuth público para ser incorporado diretamente aqui. Plugins externos precisam de API oficial e credenciais próprias.",10,0xffaaa6b8);page.addView(access);page.addView(status);page.addView(api);page.addView(note);Button close=button("VOLTAR");close.setOnClickListener(v->finish());page.addView(close);setContentView(scroll);}
    private void card(String name,String desc,String key,boolean def){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(9),dp(12),dp(8));GradientDrawable bg=new GradientDrawable();bg.setColor(0xdd171522);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),0xff3b314b);box.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);page.addView(box,lp);TextView t=label(name,13,0xff28dff4);t.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);box.addView(t);box.addView(label(desc,10,0xffc4c0ce));Switch sw=new Switch(this);sw.setText("Ativar módulo");sw.setTextColor(Color.WHITE);sw.setChecked(prefs.getBoolean(key,def));sw.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean(key,on).apply());box.addView(sw);}
    private void section(String s){TextView t=label(s,13,0xfff2154c);t.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);t.setPadding(0,dp(17),0,dp(7));page.addView(t);}
    private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.MONOSPACE);t.setPadding(0,dp(3),0,dp(3));return t;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(11);b.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);b.setTextColor(Color.WHITE);GradientDrawable d=new GradientDrawable();d.setColor(0xff211a2d);d.setCornerRadius(dp(10));d.setStroke(dp(1),0xfff2154c);b.setBackground(d);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.topMargin=dp(9);page.addView(b,p);return b;}
}